package vista;

import datos.archivoUtil;
import modelo.*;
import javax.swing.*;
import java.awt.*;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

public class ventanaPrincipal extends JFrame {
    private static final String DIR="datos/";
    private List<Producto> productos=archivoUtil.leerDatos(DIR+"productos.dat");
    private List<Cliente> clientes=archivoUtil.leerDatos(DIR+"clientes.dat");
    private List<empleado> empleados=archivoUtil.leerDatos(DIR+"empleados.dat");
    private List<bodega> bodegas=archivoUtil.leerDatos(DIR+"bodegas.dat");
    private List<inventario> inventarios=archivoUtil.leerDatos(DIR+"inventarios.dat");
    private List<ordencompra> ordenes=archivoUtil.leerDatos(DIR+"ordenes.dat");

    public ventanaPrincipal(){
        setTitle("Sistema de Inventario y Ventas");setSize(650,480);setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);
        JPanel principal=new JPanel(new BorderLayout(12,12));principal.setBorder(BorderFactory.createEmptyBorder(20,25,20,25));
        JLabel titulo=new JLabel("SISTEMA DE INVENTARIO Y VENTAS",SwingConstants.CENTER);titulo.setFont(new Font("Arial",Font.BOLD,22));principal.add(titulo,BorderLayout.NORTH);
        JPanel botones=new JPanel(new GridLayout(4,2,10,10));
        agregarBoton(botones,"Productos",()->menuProductos());agregarBoton(botones,"Clientes",()->menuClientes());
        agregarBoton(botones,"Empleados",()->menuEmpleados());agregarBoton(botones,"Bodegas",()->menuBodegas());
        agregarBoton(botones,"Inventario",()->menuInventario());agregarBoton(botones,"Órdenes y ventas",()->menuOrdenes());
        agregarBoton(botones,"Ver todos los datos",()->verResumen());agregarBoton(botones,"Salir",()->dispose());
        principal.add(botones,BorderLayout.CENTER);add(principal);
    }
    private void agregarBoton(JPanel p,String texto,Runnable accion){JButton b=new JButton(texto);b.setFont(new Font("Arial",Font.PLAIN,15));b.addActionListener(e->accion.run());p.add(b);}
    private String pedir(String mensaje){return JOptionPane.showInputDialog(this,mensaje);}
    private String pedirObligatorio(String mensaje){String s=pedir(mensaje);if(s==null)return null;s=s.trim();if(s.isEmpty()){aviso("Este dato es obligatorio.");return null;}return s;}
    private double pedirDouble(String m){try{double n=Double.parseDouble(pedirObligatorio(m));if(n<0)throw new Exception();return n;}catch(Exception e){aviso("Ingresa un número válido.");return -1;}}
    private int pedirEntero(String m){try{int n=Integer.parseInt(pedirObligatorio(m));if(n<=0)throw new Exception();return n;}catch(Exception e){aviso("Ingresa una cantidad entera mayor que cero.");return -1;}}
    private void aviso(String s){JOptionPane.showMessageDialog(this,s);}
    private boolean confirmar(String s){return JOptionPane.showConfirmDialog(this,s,"Confirmar",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
    private <T> void guardar(String archivo,List<T> lista){try{archivoUtil.guardarDatos(DIR+archivo,lista);}catch(RuntimeException e){aviso(e.getMessage());}}
    private void mostrarLista(String titulo,List<?> lista){JTextArea area=new JTextArea();area.setEditable(false);for(Object o:lista)area.append(o+"\n");if(lista.isEmpty())area.setText("No hay registros todavía.");JOptionPane.showMessageDialog(this,new JScrollPane(area),titulo,JOptionPane.INFORMATION_MESSAGE);}
    private void menuProductos(){String[] op={"Registrar","Ver productos","Modificar precio","Eliminar","Volver"};int x=JOptionPane.showOptionDialog(this,"¿Qué deseas hacer?","Productos",0,3,null,op,op[0]);if(x==0){String c=pedirObligatorio("Código:");if(c==null)return;if(buscarProducto(c)!=null){aviso("Ese código ya existe.");return;}String n=pedirObligatorio("Nombre:");if(n==null)return;String d=pedirObligatorio("Descripción:");if(d==null)return;String m=pedirObligatorio("Marca:");if(m==null)return;double p=pedirDouble("Precio:");if(p<0)return;productos.add(new Producto(c,n,d,m,p));guardar("productos.dat",productos);aviso("Producto registrado.");}else if(x==1)mostrarLista("Productos",productos);else if(x==2){Producto p=buscarProducto(pedirObligatorio("Código del producto:"));if(p==null){aviso("No se encontró el producto.");return;}double v=pedirDouble("Nuevo precio:");if(v>=0){p.setPrecio(v);guardar("productos.dat",productos);aviso("Precio actualizado.");}}else if(x==3){Producto p=buscarProducto(pedirObligatorio("Código del producto:"));if(p!=null&&confirmar("¿Eliminar "+p.getNombre()+"?")){productos.remove(p);guardar("productos.dat",productos);aviso("Producto eliminado.");}}}
    private Producto buscarProducto(String c){if(c==null)return null;for(Producto p:productos)if(p.getCodigo().equalsIgnoreCase(c))return p;return null;}
    private void menuClientes(){String[] op={"Registrar","Ver clientes","Eliminar","Volver"};int x=JOptionPane.showOptionDialog(this,"¿Qué deseas hacer?","Clientes",0,3,null,op,op[0]);if(x==0){String dpi=pedirObligatorio("DPI:");if(dpi==null)return;for(Cliente c:clientes)if(c.getDpi().equals(dpi)){aviso("Ese DPI ya está registrado.");return;}String n=pedirObligatorio("Nombre:");if(n==null)return;String d=pedirObligatorio("Dirección:");if(d==null)return;String f=pedirObligatorio("Fecha de nacimiento (dd/mm/aaaa):");if(f==null)return;String[] tipos={"Regular","VIP"};String t=(String)JOptionPane.showInputDialog(this,"Tipo de cliente:","Tipo",3,null,tipos,tipos[0]);if(t==null)return;clientes.add(new Cliente(dpi,n,d,f,t));guardar("clientes.dat",clientes);aviso("Cliente registrado.");}else if(x==1)mostrarLista("Clientes",clientes);else if(x==2){String dpi=pedirObligatorio("DPI del cliente:");Cliente c=null;for(Cliente a:clientes)if(a.getDpi().equals(dpi))c=a;if(c!=null&&confirmar("¿Eliminar cliente?")){clientes.remove(c);guardar("clientes.dat",clientes);}}}
    private void menuEmpleados(){String[] op={"Registrar","Ver empleados","Eliminar","Volver"};int x=JOptionPane.showOptionDialog(this,"¿Qué deseas hacer?","Empleados",0,3,null,op,op[0]);if(x==0){String id=pedirObligatorio("ID de empleado:");if(id==null)return;for(empleado e:empleados)if(e.getIdEmpleado().equalsIgnoreCase(id)){aviso("Ese ID ya existe.");return;}String n=pedirObligatorio("Nombre:");if(n==null)return;String dpi=pedirObligatorio("DPI:");if(dpi==null)return;String d=pedirObligatorio("Dirección:");if(d==null)return;String p=pedirObligatorio("Puesto:");if(p==null)return;double s=pedirDouble("Salario:");if(s<0)return;empleados.add(new empleado(id,n,dpi,d,p,s));guardar("empleados.dat",empleados);aviso("Empleado registrado.");}else if(x==1)mostrarLista("Empleados",empleados);else if(x==2){String id=pedirObligatorio("ID del empleado:");empleado e=null;for(empleado a:empleados)if(a.getIdEmpleado().equalsIgnoreCase(id))e=a;if(e!=null&&confirmar("¿Eliminar empleado?")){empleados.remove(e);guardar("empleados.dat",empleados);}}}
    private void menuBodegas(){String[] op={"Registrar","Ver bodegas","Volver"};int x=JOptionPane.showOptionDialog(this,"¿Qué deseas hacer?","Bodegas",0,3,null,op,op[0]);if(x==0){String id=pedirObligatorio("ID de bodega:");if(id==null)return;for(bodega b:bodegas)if(b.getidbodega().equalsIgnoreCase(id)){aviso("Ese ID ya existe.");return;}if(empleados.isEmpty()){aviso("Primero registra un empleado.");return;}String[] nombres=empleados.stream().map(e->e.getIdEmpleado()+" - "+e.getNombre()).toArray(String[]::new);int ix=JOptionPane.showOptionDialog(this,"Selecciona encargado:","Empleado",0,3,null,nombres,nombres[0]);if(ix<0)return;double cap=pedirDouble("Capacidad de la bodega:");if(cap<0)return;String d=pedirObligatorio("Dirección:");if(d==null)return;bodegas.add(new bodega(id,empleados.get(ix),cap,d));guardar("bodegas.dat",bodegas);aviso("Bodega registrada.");}else if(x==1)mostrarLista("Bodegas",bodegas);}
    private inventario obtenerInventario(){if(inventarios.isEmpty()){if(bodegas.isEmpty()){aviso("Primero registra una bodega.");return null;}String[] bs=bodegas.stream().map(b->b.getidbodega()+" - "+b.getdireccion()).toArray(String[]::new);int i=JOptionPane.showOptionDialog(this,"Selecciona la bodega del inventario:","Bodega",0,3,null,bs,bs[0]);if(i<0)return null;inventarios.add(new inventario());inventarios.get(0).setbodega(bodegas.get(i));}return inventarios.get(0);}
    private void menuInventario(){String[] op={"Agregar existencia","Ver existencias","Retirar existencia","Volver"};int x=JOptionPane.showOptionDialog(this,"¿Qué deseas hacer?","Inventario",0,3,null,op,op[0]);if(x==0){if(productos.isEmpty()){aviso("Primero registra productos.");return;}inventario inv=obtenerInventario();if(inv==null)return;String[] ps=productos.stream().map(p->p.getCodigo()+" - "+p.getNombre()).toArray(String[]::new);int i=JOptionPane.showOptionDialog(this,"Selecciona producto:","Producto",0,3,null,ps,ps[0]);if(i<0)return;int q=pedirEntero("Cantidad que deseas agregar:");if(q<0)return;inv.agregarStock(productos.get(i),q);guardar("inventarios.dat",inventarios);aviso("Existencia agregada.");}else if(x==1){if(inventarios.isEmpty()){aviso("El inventario está vacío.");return;}StringBuilder s=new StringBuilder();for(inventario inv:inventarios){s.append("Bodega: ").append(inv.getbodega()==null?"Sin asignar":inv.getbodega().getidbodega()).append("\n");for(int i=0;i<inv.getlistaproductos().size();i++)s.append(inv.getlistaproductos().get(i).getCodigo()).append(" - ").append(inv.getlistaproductos().get(i).getNombre()).append(" | Cantidad: ").append(inv.getcantidadporproducto().get(i)).append("\n");}aviso(s.toString());}else if(x==2){if(inventarios.isEmpty()){aviso("No hay existencias.");return;}inventario inv=inventarios.get(0);String c=pedirObligatorio("Código del producto:");if(c==null)return;int q=pedirEntero("Cantidad a retirar:");if(q<0)return;try{inv.retirarStock(c,q);guardar("inventarios.dat",inventarios);aviso("Existencia retirada.");}catch(IllegalArgumentException e){aviso(e.getMessage());}}}
    private void menuOrdenes(){String[] op={"Crear orden","Ver órdenes","Completar orden","Cancelar orden","Volver"};int x=JOptionPane.showOptionDialog(this,"¿Qué deseas hacer?","Órdenes y ventas",0,3,null,op,op[0]);if(x==0)crearOrden();else if(x==1)mostrarLista("Órdenes",ordenes);else if(x==2)cambiarEstado(true);else if(x==3)cambiarEstado(false);}
    private void crearOrden(){if(clientes.isEmpty()){aviso("Primero registra un cliente.");return;}if(productos.isEmpty()){aviso("Primero registra productos.");return;}if(inventarios.isEmpty()){aviso("Primero agrega productos al inventario.");return;}String[] cs=clientes.stream().map(c->c.getDpi()+" - "+c.getNombre()).toArray(String[]::new);int ci=JOptionPane.showOptionDialog(this,"Selecciona cliente:","Cliente",0,3,null,cs,cs[0]);if(ci<0)return;String id="ORD-"+(ordenes.size()+1);ordencompra o=new ordencompra(id,clientes.get(ci).getNombre(),LocalDate.now().toString());boolean seguir=true;while(seguir){String[] ps=productos.stream().map(p->p.getCodigo()+" - "+p.getNombre()+" (Q"+p.getPrecio()+")").toArray(String[]::new);int pi=JOptionPane.showOptionDialog(this,"Selecciona producto para agregar:","Productos",0,3,null,ps,ps[0]);if(pi<0)break;int q=pedirEntero("Cantidad:");if(q<0)continue;o.agregarDetalle(productos.get(pi),q);seguir=confirmar("Producto agregado. ¿Deseas agregar otro?");}if(o.getDetalles().isEmpty()){aviso("No se creó la orden porque no tiene productos.");return;}o.setestado("Pendiente");ordenes.add(o);guardar("ordenes.dat",ordenes);aviso("Orden creada. Total: Q"+String.format("%.2f",o.gettotal())+"\nPara descontar existencias, selecciona Completar orden.");}
    private void cambiarEstado(boolean completar){String id=pedirObligatorio("Código de la orden:");if(id==null)return;ordencompra o=null;for(ordencompra a:ordenes)if(a.getIdOrden().equalsIgnoreCase(id))o=a;if(o==null){aviso("No se encontró la orden.");return;}if(!"Pendiente".equalsIgnoreCase(o.getestado())){aviso("La orden ya fue procesada.");return;}if(completar){if(inventarios.isEmpty()){aviso("No existe inventario.");return;}inventario inv=inventarios.get(0);try{java.util.Map<String,Integer> cantidades=new java.util.HashMap<>();for(DetalleOrden d:o.getDetalles())cantidades.put(d.getProducto().getCodigo(),cantidades.getOrDefault(d.getProducto().getCodigo(),0)+d.getCantidad());for(java.util.Map.Entry<String,Integer> e:cantidades.entrySet())if(inv.consultarCantidad(e.getKey())<e.getValue())throw new IllegalArgumentException("Existencia insuficiente para el producto: "+e.getKey());for(java.util.Map.Entry<String,Integer> e:cantidades.entrySet())inv.retirarStock(e.getKey(),e.getValue());o.setInventarioDescontado(true);o.setestado("Completada");guardar("inventarios.dat",inventarios);guardar("ordenes.dat",ordenes);aviso("Venta completada. El inventario fue actualizado. Total: Q"+String.format("%.2f",o.gettotal()));}catch(IllegalArgumentException e){aviso(e.getMessage());}}else if(confirmar("¿Cancelar la orden "+id+"?")){o.setestado("Cancelada");guardar("ordenes.dat",ordenes);aviso("Orden cancelada. No se descontó inventario.");}}
    private void verResumen(){aviso("Productos: "+productos.size()+"\nClientes: "+clientes.size()+"\nEmpleados: "+empleados.size()+"\nBodegas: "+bodegas.size()+"\nÓrdenes: "+ordenes.size());}
    public static void main(String[] args){SwingUtilities.invokeLater(()->new ventanaPrincipal().setVisible(true));}
}
